<script setup lang="ts">
import { computed, ref } from 'vue'
import { app, setLlm } from '../session'
import { PROVIDERS, listModels, test } from '../dm/llm'
const P = computed(() => PROVIDERS.find(p => p.id === app.llm.provider)!); const models = ref<string[]>([]), msg = ref(''), bad = ref(false), busy = ref(false)
const pick = (id: string) => { setLlm({ provider: id as any, model: '', url: '' }); models.value = []; msg.value = '' }; const find = async () => { busy.value = true; try { models.value = await listModels(app.llm); msg.value = `${models.value.length} models offered.`; bad.value = false } catch (e: any) { msg.value = e?.message ?? 'Could not ask.'; bad.value = true } busy.value = false }; const tryIt = async () => { busy.value = true; msg.value = ''; try { msg.value = '“' + await test(app.llm) + '”'; bad.value = false } catch (e: any) { msg.value = e?.message ?? 'It failed.'; bad.value = true } busy.value = false }
</script>
<template><div class="chips"><button v-for="p in PROVIDERS" :key="p.id" class="chip s" :class="{ on: app.llm.provider === p.id }" @click="pick(p.id)">{{ p.name }}</button></div><p class="muted" style="margin:8px 0 0">{{ P.note }} <a v-if="P.link" class="link" :href="P.link" target="_blank" rel="noopener">Get a key</a></p>
  <template v-if="app.llm.provider !== 'off'"><template v-if="P.needKey"><label class="lab" for="lk">API key. It stays in this browser and is sent only to {{ P.name }}</label><input id="lk" class="field" type="password" autocomplete="off" :value="app.llm.key" @change="setLlm({ key: ($event.target as HTMLInputElement).value.trim() })"></template><template v-if="P.id === 'local'"><label class="lab" for="lu">Address</label><input id="lu" class="field" :value="app.llm.url || P.url" @change="setLlm({ url: ($event.target as HTMLInputElement).value.trim() })"></template><template v-if="P.id !== 'chrome'"><label class="lab" for="lm">Model</label><div class="row"><input id="lm" class="field" list="llm-models" :placeholder="P.model" :value="app.llm.model" @change="setLlm({ model: ($event.target as HTMLInputElement).value.trim() })"><datalist id="llm-models"><option v-for="m in models" :key="m" :value="m" /></datalist><button class="btn" :disabled="busy" @click="find">List</button></div></template><button class="opt" :class="{ on: app.llm.narrate }" @click="setLlm({ narrate: !app.llm.narrate })"><i class="tick" /><span>Let it also describe rooms and fights (uses more)</span></button><div class="row"><button class="btn" :disabled="busy" @click="tryIt">{{ busy ? 'Asking…' : 'Try it' }}</button><span class="grow" :style="{ color: bad ? 'var(--bad)' : 'var(--good)' }">{{ msg }}</span></div></template></template>
